VALUES ('5d81e91a-d56f-45ff-b064-cc0171d0da92', NULL, NULL, NULL, '{"summary": "Coimma tem liderança sólida em pecuária, mas precisa acelerar serviços recorrentes e IoT para defender posição contra disrupção tecnológica e juros altos.", "threats": [{"source": "fato", "content": "SELIC 14,90% inibe investimentos em Capex dos clientes, alongando ciclo de vendas", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Disrupção por visão computacional pode substituir balanças tradicionais em 5-10 anos", "confidence": "Média"}, {"source": "análise de mercado", "content": "Concorrentes migrando para modelos de assinatura software+hardware capturam recorrência", "confidence": "Média"}, {"source": "fato", "content": "Câmbio a R$5,34 encarece componentes eletrônicos importados e pressiona margens", "confidence": "Alta"}], "strengths": [{"source": "fato", "content": "Liderança de marca consolidada há 70+ anos no segmento pecuário com Top of Mind", "confidence": "Alta"}, {"source": "fato", "content": "Capacidade fabril verticalizada (estrutura metálica + eletrônica) reduz dependência externa", "confidence": "Alta"}, {"source": "fato", "content": "Portfólio diversificado entre pecuária (70%) e grãos (30%) mitiga riscos setoriais", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Rede de assistência técnica estabelecida como barreira competitiva e canal de expansão", "confidence": "Média"}], "weaknesses": [{"source": "fato", "content": "Receita de serviços recorrentes representa apenas 5% - base instalada submonetizada", "confidence": "Alta"}, {"source": "fato", "content": "Ausência de estrutura comercial e técnica para atender segmento industrial não-agro", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Dependência cíclica do preço da arroba do boi impacta previsibilidade de receita", "confidence": "Média"}, {"source": "estimativa", "content": "Maturidade digital intermediária (6/10) limita oferta de soluções IoT integradas", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Rastreabilidade bovina obrigatória via RFID cria demanda imediata para balanças conectadas", "confidence": "Alta"}, {"source": "estimativa", "content": "Expansão de contratos de manutenção/calibração na base instalada (de 5% para 15%+)", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Parcerias com Agrotechs para monetização de dados de pesagem via plataforma IoT", "confidence": "Média"}, {"source": "fato", "content": "Plano Safra com taxas equalizadas facilita financiamento de Capex para produtores", "confidence": "Alta"}]}'::jsonb, '{"legal": ["Homologação INMETRO obrigatória é barreira de entrada alta - vantagem competitiva para players estabelecidos como Coimma", "Portarias INMETRO para instrumentos de pesagem não automática exigem conformidade contínua e investimento em certificação", "Rastreabilidade individual bovina obrigatória iminente - oportunidade estratégica para balanças com RFID integrado"], "social": ["Produtor rural cauteloso com investimentos devido aos juros altos - necessidade de demonstrar ROI claro e rápido", "Crescente demanda por conectividade no campo eleva expectativa por equipamentos IoT integrados a softwares de gestão", "Normas de bem-estar animal impactam design de troncos - oportunidade de diferenciação por inovação em manejo humanizado"], "summary": "Cenário desafiador com SELIC 14,90% e câmbio alto pressiona vendas de Capex. Oportunidades claras em rastreabilidade obrigatória (RFID) e IoT. Ameaça de disrupção por visão computacional. Priorizar financiamento facilitado e serviços recorrentes.", "economic": ["SELIC a 14,90% a.a. inibe decisão de compra de bens de capital - exige estratégias de financiamento próprio ou parcerias", "Câmbio USD/BRL 5,34 encarece eletrônica embarcada importada, pressionando margens e competitividade de preço", "Volatilidade do preço do boi gordo gera cautela no produtor rural, impactando diretamente 70% do faturamento da Coimma"], "political": ["Plano Safra com taxas equalizadas é crítico para viabilizar vendas de equipamentos de alto valor (Capex) ao produtor rural", "Estabilidade política com foco em reformas econômicas favorece previsibilidade para investimentos industriais de longo prazo", "Exigências crescentes de rastreabilidade na cadeia da carne criam demanda compulsória por balanças com tecnologia RFID"], "environmental": ["Preços do aço (insumo principal) estáveis com viés de alta - monitorar para proteger margens de fabricação", "Cadeia de suprimentos normalizada, mas dependência de eletrônica importada expõe a riscos cambiais e logísticos", "Pressão por sustentabilidade na pecuária pode exigir certificações ambientais para equipamentos no médio prazo"], "technological": ["Pecuária de Precisão com IoT é tendência-chave - Coimma deve acelerar integração de dados de pesagem com ERPs rurais", "Ameaça emergente: balanças baseadas em visão computacional (câmeras) podem disruptar modelo tradicional de pesagem", "Concorrentes focando em modelos de assinatura de software acoplado ao hardware - risco de comoditização do equipamento"]}'::jsonb, '{"summary": "Setor com atratividade média: barreiras de entrada protegem incumbentes como Coimma, mas poder de compra elevado (SELIC 14,90%) e ameaça de substitutos tecnológicos exigem ação. Oportunidades claras em parcerias com Agrotechs, monetização de dados via IoT/RFID e expansão de serviços recorrentes. Prioridade: transformar hardware em plataforma de dados para capturar valor da pecuária de precisão.", "buyer_power": "Poder alto. Produtor rural cauteloso com SELIC 14,90%. Decisão de Capex adiada pela volatilidade do boi gordo. Plano Safra com taxas equalizadas é alavanca crítica para viabilizar vendas no curto prazo.", "supplier_power": "Poder moderado. Aço com preços estáveis mas viés de alta. Câmbio a R$5,34 encarece eletrônica embarcada importada. Verticalização da Coimma (estrutura+eletrônica própria) mitiga dependência crítica de fornecedores.", "disruption_ai_data": "Disrupção média-alta. Pecuária de precisão exige IoT e analytics. Rastreabilidade individual bovina obrigatória favorece balanças com RFID integrado. Coimma deve monetizar dados de pesagem como serviço recorrente.", "threat_substitutes": "Ameaça média-crescente. Balanças por visão computacional (câmeras) eliminam hardware tradicional. Adoção tecnológica média-alta no campo acelera risco. Coimma deve integrar IA aos produtos para não ser substituída.", "competitive_rivalry": "Rivalidade média-alta com Toledo, Beckhauser e regionais. Concorrentes migrando para modelos de assinatura software+hardware. Coimma lidera em balanças de tronco, mas precisa defender posição com diferenciação tecnológica IoT.", "threat_new_entrants": "Ameaça baixa. Barreiras altas: homologação INMETRO obrigatória, ISO 9001, rede de assistência técnica nacional e confiança de marca (Coimma: 74 anos). Novos entrantes enfrentam ciclo longo de credenciamento.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Média", "strategic_implications": ["Estruturar financiamento via Plano Safra e BNDES Finame para neutralizar poder de barganha do comprador em cenário de SELIC 14,90%", "Acelerar integração IoT/RFID nas balanças bovinas para capturar demanda de rastreabilidade obrigatória e criar receita recorrente de dados", "Firmar parcerias com Agrotechs e ERPs rurais para criar ecossistema de dados integrado, blindando contra substitutos de visão computacional", "Expandir serviços de calibração/manutenção (hoje 5%) para 15% do faturamento, monetizando base instalada e reduzindo ciclicidade"], "supplier_power_intensity": "Média", "disruption_ai_data_intensity": "Média", "threat_substitutes_intensity": "Média", "competitive_rivalry_intensity": "Média", "power_partnerships_ecosystems": "Oportunidade alta. Consolidação de Agrotechs cria espaço para parcerias em software de gestão pecuária. Integração de dados de pesagem com ERPs rurais e plataformas de rastreabilidade é diferencial competitivo estratégico.", "threat_new_entrants_intensity": "Baixa", "power_partnerships_ecosystems_intensity": "Alta"}'::jsonb, '{"summary": "90 dias focados em monetizar base instalada via serviços recorrentes e especificar solução RFID, preparando lançamento comercial para meses 4-6 e escala no segundo semestre.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Estruturar programa de serviços recorrentes e mapear base instalada para conversão em contratos", "investment": "R$ 25-35 mil", "key_results": ["Mapear 100% da base instalada ativa dos últimos 5 anos (estimativa: 2.000-3.000 equipamentos)", "Desenvolver 3 pacotes de serviços (Bronze/Prata/Ouro) com precificação e SLAs definidos", "Treinar 100% da equipe comercial e técnica nos novos pacotes de serviços (estimativa: 15-20 pessoas)"], "aligned_recommendation": "Programa de Maximização da Base Instalada - Serviços Recorrentes e Contratos de Manutenção"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Lançar programa comercial de serviços e iniciar especificação técnica da solução RFID integrada", "investment": "R$ 40-55 mil", "key_results": ["Converter 50 clientes da base instalada para contratos de manutenção (meta: 2-3% da base)", "Concluir especificação técnica do pacote balança + RFID + software com fornecedores homologados", "Contratar consultoria INMETRO para roadmap de homologação do novo produto integrado"], "aligned_recommendation": "Lançamento de Solução Integrada de Pesagem com RFID para Rastreabilidade Bovina"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Consolidar receita recorrente inicial e validar protótipo RFID com clientes-piloto", "investment": "R$ 55-70 mil", "key_results": ["Atingir R$ 80-100 mil em contratos de serviços recorrentes assinados (MRR)", "Instalar protótipo funcional de balança+RFID em 2 confinamentos parceiros para validação", "Documentar requisitos de P&D industrial (Fase 2) com mapeamento de 10 potenciais clientes-alvo"], "aligned_recommendation": "Lançamento de Solução Integrada de Pesagem com RFID para Rastreabilidade Bovina"}], "success_metrics": ["Receita de serviços recorrentes saltando de 5% para 7-8% do faturamento ao final dos 90 dias", "Base de 80-100 contratos de manutenção ativos com SLA definido", "Protótipo RFID validado em campo com feedback documentado de 2 clientes reais"], "execution_phases": {"scale": {"focus": "Expansão comercial e preparação Fase 2 Industrial", "duration": "Meses 7-12", "objectives": ["Lançar comercialmente solução RFID integrada no mercado pecuário", "Elevar receita de serviços para meta de 15% do faturamento", "Iniciar estruturação comercial para segmento industrial (condicionado à SELIC < 12%)"], "key_results": ["50+ unidades da solução RFID vendidas no primeiro semestre de lançamento", "Receita de serviços representando 15% do faturamento total", "Célula de P&D industrial operacional com 2-3 engenheiros dedicados"], "prerequisites": ["Homologação INMETRO obtida para solução RFID", "Receita de serviços sustentável acima de 12% do faturamento", "Validação positiva do produto RFID em campo"], "investment_range": "R$ 200-300 mil"}, "foundation": {"focus": "Estruturação de serviços recorrentes e especificação técnica RFID", "duration": "Meses 1-3", "objectives": ["Criar infraestrutura comercial para venda de serviços recorrentes", "Especificar e iniciar desenvolvimento da solução integrada RFID", "Preparar documentação para homologação INMETRO"], "key_results": ["80-100 contratos de manutenção assinados", "Protótipo RFID instalado em 2 clientes-piloto", "Roadmap INMETRO aprovado com consultoria especializada"], "investment_range": "R$ 120-160 mil", "capacity_requirements": {"team": "8-10 pessoas dedicadas parcialmente (comercial, técnico, engenharia)", "dependencies": ["Acesso ao histórico completo da base instalada (CRM/ERP)", "Disponibilidade de clientes parceiros para piloto RFID", "Contratação de consultoria INMETRO"], "skills_needed": ["Gestão de contratos de serviços", "Engenharia de produto (eletrônica/RFID)", "Conhecimento regulatório INMETRO"]}}, "validation": {"focus": "Pilotos comerciais e validação de produto RFID", "duration": "Meses 4-6", "objectives": ["Escalar programa de serviços para 200+ contratos", "Validar solução RFID em 5-8 confinamentos de médio/grande porte", "Testar modelo de assinatura mensal para software de gestão"], "key_results": ["Receita de serviços atingindo 10% do faturamento", "5-8 instalações RFID com feedback positivo documentado", "Modelo de precificação por assinatura validado com 3+ clientes pagantes"], "prerequisites": ["Programa de serviços recorrentes operacional", "Protótipo RFID funcional validado em campo", "Processo de homologação INMETRO iniciado"], "investment_range": "R$ 150-200 mil"}}, "total_investment": "R$ 120-160 mil", "capacity_assessment": {"blockers": ["Qualidade e completude dos dados da base instalada no sistema atual", "Tempo de resposta da consultoria INMETRO para roadmap de homologação", "Disponibilidade de clientes-piloto dispostos a testar protótipo RFID sem custo inicial"], "team_readiness": "Média", "budget_adequacy": "Suficiente", "stakeholder_alignment": "Alinhado"}}'::jsonb, '{"roadmap": ["Curto Prazo (3-6 meses): Monetizar base instalada com contratos de calibração/manutenção; especificar e prototipar solução RFID nativa; estruturar parcerias com financeiras para Plano Safra", "Médio Prazo (6-12 meses): Lançar comercialmente balanças IoT/RFID; expandir receita de serviços para 10% do faturamento; pilotar modelo de assinatura de dados com 5 clientes âncora", "Longo Prazo (12+ meses): Escalar plataforma de dados pecuária; avaliar entrada industrial conforme cenário macroeconômico; buscar parcerias/aquisições de Agrotechs complementares"], "key_findings": ["Migrar de venda transacional para modelo de receita recorrente via serviços e assinaturas IoT protege contra ciclos do boi gordo", "Integração com Agrotechs posiciona Coimma como hub de dados da cadeia pecuária, criando barreira competitiva", "Base instalada é ativo subutilizado: expandir calibração/manutenção de 5% para 15% do faturamento em 18 meses"], "main_findings": ["FORÇA: Liderança de marca consolidada (70+ anos) com capacidade fabril verticalizada e portfólio diversificado pecuária/grãos", "FRAQUEZA: Receita de serviços representa apenas 5% do faturamento, desperdiçando potencial da base instalada de clientes", "OPORTUNIDADE: Rastreabilidade bovina obrigatória com RFID e demanda crescente por pecuária de precisão com IoT", "AMEAÇA: Disrupção por visão computacional e SELIC a 14,90% inibindo investimentos em Capex pelos clientes"], "important_notes": ["SELIC a 14,90% exige foco em financiamento facilitado via Plano Safra para viabilizar vendas de equipamentos", "Postergar investimentos pesados na Fase 2 industrial até SELIC recuar abaixo de 12%", "Monitorar ativamente ameaça de balanças baseadas em visão computacional (câmeras)"], "central_challenge": "Transformar a Coimma de fabricante de equipamentos em plataforma de pecuária de precisão, expandindo vendas com portfólio atual (Fase 1) enquanto prepara entrada no segmento industrial (Fase 2), em cenário de SELIC a 14,90%.", "executive_summary": "A Coimma, líder em balanças pecuárias com 70+ anos de mercado, enfrenta pressão de juros altos e ameaça de disrupção tecnológica. A estratégia em duas fases deve priorizar monetização da base instalada via serviços recorrentes e IoT/RFID (Fase 1), postergando investimentos industriais até SELIC recuar. A oportunidade de rastreabilidade bovina obrigatória é o principal vetor de crescimento imediato.", "strategic_priorities": ["Fase 1: Expandir serviços recorrentes e financiamento facilitado para maximizar vendas atuais", "Fase 1: Lançar solução RFID/IoT integrada para capturar onda de rastreabilidade obrigatória", "Fase 2: Preparar entrada industrial apenas após validação de modelo recorrente e queda de juros"], "consistency_validation": {"flags": ["Fase 2 industrial deve aguardar SELIC < 12% para viabilidade financeira", "Capacidade de desenvolvimento IoT/software pode requerer parceria ou contratação especializada"], "legal_alignment": true, "capacity_alignment": true, "financial_alignment": true, "overall_realism_score": 8}, "overall_recommendation": "Executar Fase 1 com urgência focando em serviços recorrentes e RFID, postergando Fase 2 industrial até cenário macroeconômico favorável. A transformação em plataforma de dados é o caminho para defender liderança e criar valor sustentável."}'::jsonb, '{"sam": "R$ 2.8B - 4.2B", "som": "R$ 180M - 320M", "tam": "R$ 8.5B - 12.0B", "cagr": "+6.5% a.a. (baseado em: crescimento moderado do setor impactado por SELIC 14.9%)", "summary": "Coimma opera em mercado de R$8-12B com SAM de R$2.8-4.2B. Posição de líder consolidado permite capturar R$180-320M (6-8% share). Fase 1 pode dobrar receita; Fase 2 adiciona R$40-80M.", "assumptions": ["TAM: Mercado brasileiro de balanças industriais + equipamentos pecuários (ABIMAQ 2024: R$10B setor)", "SAM: 35% do TAM = segmentos pecuária, grãos e balanças rodoviárias onde Coimma compete", "SOM: 6-8% market share realista para líder consolidado com 70+ anos e rede nacional"], "sam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 2.8B - 3.6B"}, "optimistic": {"probability": 20, "value_range": "R$ 3.6B - 4.2B"}, "conservative": {"probability": 30, "value_range": "R$ 2.2B - 2.8B"}}, "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 180M - 250M", "market_share": "6-7%"}, "optimistic": {"probability": 20, "value_range": "R$ 250M - 320M", "market_share": "7-8%"}, "conservative": {"probability": 30, "value_range": "R$ 120M - 180M", "market_share": "5-6%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 8.5B - 10.5B"}, "optimistic": {"probability": 20, "value_range": "R$ 10.5B - 12.0B"}, "conservative": {"probability": 30, "value_range": "R$ 7.0B - 8.5B"}}, "confidence_level": 68, "calculation_notes": "Coimma fatura R$50-100M (5-8% do SAM). Toledo Brasil lidera com ~R$800M. Mercado fragmentado com 5-7 players relevantes. Crescimento limitado por juros altos.", "data_sources_used": {"direct_data": ["Receita estimada Coimma: R$50-100M/ano (LinkedIn/perfil)", "CNPJ ativo desde 1951, 100-200 funcionários", "70% pecuária, 30% grãos/industrial, 5% serviços"], "proxy_calculations": ["Toledo do Brasil (líder): ~R$800M-1B receita (proxy por funcionários ~2.500)", "5 concorrentes principais somam ~R$1.5B em receita estimada", "Mercado total = soma players × fator fragmentação (2.5x)"], "benchmark_extrapolations": ["ABIMAQ: setor máquinas agrícolas R$45B, pesagem ~22% = R$10B", "Agronegócio Brasil: TAM R$1.2T, equipamentos ~1% = R$12B", "Crescimento setorial IBGE: +5-8% a.a. pré-ajuste juros"]}, "estimation_method": "proxy_concorrentes", "baseline_recommendation": "realistic"}'::jsonb, '{"summary": "A Coimma lidera em balanças de tronco com marca consolidada (70+ anos), mas apresenta gaps críticos em monetização de serviços recorrentes e presença industrial. Toledo do Brasil é o benchmark principal: domina serviços (15-20% da receita vs. 5% Coimma), possui rede técnica 3x maior e lidera no segmento industrial-alvo da Fase 2. Beckhauser e Progresso destacam-se em integração digital e programas de fidelização. Para a Fase 1, priorizar contratos de manutenção da base instalada pode adicionar R$5-8M/ano. Para a Fase 2, replicar o modelo de capilaridade técnica da Toledo é crítico para credibilidade no mercado industrial, onde tempo de resposta é fator decisivo de compra.", "best_practices": ["Toledo: Rede de 200+ assistências técnicas credenciadas com SLA de 24h - benchmark para expansão Fase 2", "Beckhauser: Integração nativa com softwares de gestão pecuária (JetBov, Ideagri) aumenta valor percebido", "Progresso: Programa de troca com bônus para upgrade tecnológico - acelera renovação da base instalada"], "performance_gaps": ["Receita de serviços recorrentes (5%) muito abaixo de Toledo (15-20%) - potencial de R$10-15M não capturado", "Ausência de modelo SaaS/assinatura para software de gestão integrado às balanças, já oferecido por concorrentes", "Penetração industrial quase nula vs. Toledo que domina 40% do segmento de balanças industriais no Brasil"], "competitors_analyzed": ["Toledo do Brasil (Prix)", "Beckhauser", "Troncos e Balanças Progresso", "Açores Troncos e Balanças", "Romancini"]}'::jsonb, '{"raise": ["Conectividade IoT nativa em 100% das balanças eletrônicas", "Receita recorrente de serviços de 5% para 20% do faturamento", "Integração com softwares de gestão pecuária e ERPs industriais"], "create": ["Plataforma de dados de pesagem como serviço (PaaS) por assinatura", "Balança com RFID integrado para rastreabilidade individual bovina", "Ecossistema de parcerias com Agrotechs para monetização de dados"], "reduce": ["Complexidade de modelos de balanças com baixo giro no portfólio", "Ciclo de vendas longo baseado apenas em visitas presenciais", "Investimento em hardware genérico sem diferenciação tecnológica"], "summary": "A Coimma deve migrar do modelo transacional de venda de equipamentos para um ecossistema de pecuária de precisão. Eliminando a venda única sem vínculo e criando uma plataforma de dados por assinatura com balanças IoT/RFID nativas, a empresa transforma hardware em fonte de receita recorrente. A integração com Agrotechs e softwares de gestão posiciona a Coimma como hub de inteligência da cadeia pecuária, blindando-a contra substitutos tecnológicos (visão computacional) e reduzindo a dependência cíclica do preço do boi. Na Fase 2, essa competência em plataformas conectadas diferencia a entrada no segmento industrial, onde automação e dados são pré-requisitos competitivos.", "eliminate": ["Venda transacional única sem vínculo pós-venda com o cliente", "Relatórios manuais de pesagem em papel sem integração digital", "Dependência exclusiva de revendedores sem relacionamento direto"], "new_value_curve": "De fabricante de hardware para plataforma de inteligência de pesagem conectada, capturando valor recorrente via dados e serviços."}'::jsonb, '{"summary": "Acelerar aquisição via financiamento facilitado e indicações, enquanto expande LTV monetizando base instalada com serviços recorrentes de calibração e IoT.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Prospecção via feiras agro (Agrishow, Feicorte), parcerias com revendas rurais e campanhas digitais segmentadas por região produtora.", "Engage: Demonstrações in loco em fazendas-modelo, webinars sobre pecuária de precisão e calculadora online de ROI em pesagem.", "Activate: Financiamento facilitado via Plano Safra, proposta técnica em 48h e visita de engenheiro para dimensionamento gratuito.", "Propagate: Programa de indicação com bônus em serviços, cases de sucesso em vídeo com pecuaristas influentes e selos ''Powered by Coimma''."], "metrics": ["CAC por canal (feiras vs. digital vs. indicação)", "Taxa de conversão visita técnica → proposta → fechamento", "Coeficiente viral (indicações por cliente ativo)", "Tempo médio do ciclo de vendas"], "bottleneck": "Ciclo de vendas longo devido à SELIC de 14.90% que inibe Capex do produtor; necessidade de oferecer condições financeiras diferenciadas."}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Instalação com treinamento completo, suporte técnico 24h via WhatsApp e integração com softwares de gestão do cliente.", "Convert: Contratos anuais de calibração obrigatória INMETRO, planos de manutenção preventiva e venda de peças de reposição originais.", "Loop Back: Alertas automáticos de vencimento de calibração, programa de fidelidade com descontos progressivos e check-ups semestrais.", "Expand: Upsell de módulos IoT/conectividade, cross-sell entre linhas (pecuária→rodoviária→grãos) e upgrade de balanças antigas."], "metrics": ["LTV médio por cliente (equipamento + serviços em 10 anos)", "Taxa de adesão a contratos de manutenção recorrente", "Receita de serviços como % do faturamento (meta: 5%→15%)", "NPS e taxa de recompra/expansão de portfólio"], "bottleneck": "Serviços representam apenas 5% do faturamento; base instalada submonetizada por falta de oferta ativa de contratos recorrentes."}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC permanece entre 13-15% até 2026. Câmbio oscila entre R$5,20-5,50, pressionando margens em eletrônica. Produtor rural cauteloso posterga investimentos em Capex. Plano Safra mantém taxas equalizadas como principal alavanca de vendas. Rastreabilidade avança gradualmente. Concorrentes intensificam modelos de assinatura de software. Crescimento moderado de 8-12% a.a. exige foco em serviços recorrentes e financiamento facilitado.", "probability": 60, "required_actions": ["Estruturar parcerias com bancos para financiamento via Plano Safra e BNDES Finame", "Lançar modelo de assinatura combinando hardware + software + manutenção", "Elevar receita de serviços de 5% para 12% explorando base instalada de 70 anos", "Desenvolver versão IoT de balanças existentes com upgrade modular"]}, "summary": "A Coimma opera em cenário desafiador com SELIC a 14,90% inibindo Capex e câmbio a R$5,34 pressionando custos. O cenário realista (60%) exige foco imediato em financiamento facilitado via Plano Safra, expansão de serviços recorrentes e modelos de assinatura. A oportunidade regulatória de rastreabilidade bovina com RFID é o principal vetor de crescimento. A ameaça de visão computacional requer monitoramento ativo. Recomenda-se postergar investimentos pesados na Fase 2 industrial até SELIC recuar abaixo de 12%, priorizando a Fase 1 com portfólio atual e maximização da base instalada.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC recua para 11% até 2026, Plano Safra amplia taxas equalizadas e rastreabilidade individual bovina torna-se obrigatória. Câmbio estabiliza em R$4,80, reduzindo custo de eletrônica embarcada. Demanda por balanças com RFID explode. Coimma captura 40% do mercado de rastreabilidade. Receita de serviços salta para 15% com contratos de manutenção IoT. Expansão industrial acelera com custo de capital menor.", "probability": 20, "required_actions": ["Acelerar lançamento de balanças com RFID integrado para capturar demanda regulatória", "Estruturar pacotes de financiamento próprio aproveitando custo de capital menor", "Expandir equipe comercial industrial em 50% para capturar janela de oportunidade", "Firmar parcerias com Agrotechs para integração de dados de pesagem"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 16%+, câmbio ultrapassa R$6,00. Plano Safra sofre cortes orçamentários. Preço do boi gordo despenca, paralisando investimentos em pecuária. Aço sobe 25%, comprimindo margens. Startups de visão computacional ganham tração, ameaçando balanças tradicionais. Vendas caem 20%. Fase 2 industrial é adiada. Coimma entra em modo de sobrevivência, priorizando caixa e serviços.", "probability": 20, "required_actions": ["Cortar custos fixos em 15% e postergar investimentos na Fase 2 industrial", "Pivotar para serviços de manutenção e calibração como receita principal", "Desenvolver parcerias ou licenciamento com startups de visão computacional", "Focar em mercado de reposição e upgrades da base instalada"]}, "mitigation_tactics": ["Diversificar receita: elevar serviços recorrentes de 5% para 15% em 24 meses, reduzindo dependência de Capex", "Hedge cambial: contratar proteção para 60% das compras de componentes eletrônicos importados", "Monitorar tecnologias disruptivas: criar célula de inovação para avaliar visão computacional e IA", "Flexibilizar estrutura de custos: terceirizar etapas não-críticas da produção para ajustar capacidade rapidamente"], "early_warning_signals": ["Decisões do COPOM sobre SELIC acima de 15% ou abaixo de 12% indicam mudança de cenário", "Publicação de portarias do MAPA sobre rastreabilidade obrigatória acelera demanda por RFID", "Câmbio sustentado acima de R$5,80 por 60 dias sinaliza pressão crítica em margens", "Anúncios de captação de startups de visão computacional para agro indicam ameaça competitiva", "Variação do preço da arroba do boi acima de 15% em 90 dias altera comportamento de compra"]}'::jsonb, '{"summary": "O BSC alinha a transformação da Coimma de fabricante transacional para hub de inteligência pecuária. Os objetivos financeiros priorizam receita recorrente e margem via serviços. A perspectiva de clientes foca em engajamento na plataforma e satisfação. Processos internos direcionam o desenvolvimento de produtos IoT e estrutura de sucesso do cliente. Aprendizado sustenta a mudança cultural para vendas consultivas e capacidades digitais, preparando a Fase 2 industrial.", "customer": ["Atingir 40% da base instalada ativa na plataforma de pecuária de precisão", "Conquistar NPS acima de 70 com proposta de valor baseada em inteligência de dados"], "financial": ["Elevar receita recorrente (assinaturas IoT) de 5% para 20% do faturamento em 3 anos", "Aumentar margem EBITDA em 5 p.p. via monetização de dados e serviços conectados"], "learning_growth": ["Capacitar 100% da equipe comercial em venda consultiva de soluções recorrentes", "Desenvolver competências internas em ciência de dados e plataformas digitais"], "internal_processes": ["Lançar linha de balanças IoT/RFID nativas em 18 meses com integração a Agrotechs", "Estruturar área de Customer Success para gestão de assinaturas e upsell"]}'::jsonb, '{"score": "8.2/10", "summary": "A Coimma deve priorizar a consolidação de sua liderança no segmento pecuário através de três frentes: (1) capitalizar a oportunidade regulatória de rastreabilidade bovina com solução integrada balança+RFID+software, (2) transformar sua base instalada de 70+ anos em receita recorrente de serviços, elevando de 5% para 15% do faturamento, e (3) preparar a entrada no segmento industrial sem comprometer caixa até que o cenário macroeconômico seja mais favorável. O cenário de SELIC a 14,90% inviabiliza investimentos pesados em nova estrutura comercial industrial, mas o Plano Safra oferece alavanca para vendas no agro. A ameaça de visão computacional deve ser monitorada trimestralmente. Próximos passos imediatos: (1) iniciar desenvolvimento do pacote RFID integrado, (2) lançar programa de contratos de manutenção para base instalada, (3) contratar consultoria INMETRO para acelerar homologações.", "criteria": ["ROI e Payback (Retorno sobre investimento em cenário de SELIC 14,90%)", "Risco Operacional e de Mercado (Exposição a volatilidade e dependência de Capex do cliente)", "Alinhamento Estratégico e Aproveitamento de Competências Existentes"], "alternatives": ["Alternativa A: Expansão Agressiva em Pecuária com RFID + Serviços Recorrentes (Fase 1 Intensificada)", "Alternativa B: Diversificação Imediata para Segmento Industrial (Fase 2 Antecipada)", "Alternativa C: Estratégia Híbrida Sequencial - Consolidar Pecuária (Fase 1) e Preparar Industrial (Fase 2 Condicionada à SELIC)"], "review_cycle": {"frequency": "Trimestral", "extraordinary_triggers": ["SELIC recuar abaixo de 12% a.a. (gatilho para acelerar Fase 2)", "Publicação de regulamentação obrigatória de rastreabilidade bovina individual", "Entrada de competidor com solução de visão computacional em escala comercial", "Variação cambial USD/BRL superior a 15% em 60 dias (impacto em custos de eletrônica)", "Mudança regulatória INMETRO que exija >10% de ajuste de custo em produtos", "Falha de compliance LGPD ou setorial que afete operação de software", "Aquisição ou fusão relevante entre concorrentes diretos"]}, "score_comparison": "+31% acima da Alternativa B e +12% acima da Alternativa A", "monitoring_metrics": ["Receita de Serviços Recorrentes como % do Faturamento Total (Meta: 15% em 18 meses)", "Número de Unidades com RFID Integrado Vendidas (Meta: 200 unidades em 12 meses)", "Taxa de Conversão de Base Instalada para Contratos de Manutenção (%)", "Ticket Médio por Cliente (evolução com upsell de serviços e IoT)", "NPS (Net Promoter Score) de Clientes Pecuária e Grãos", "Pipeline Qualificado para Segmento Industrial (valor em R$ e número de oportunidades)", "Tempo Médio de Homologação INMETRO para Novos Produtos"], "recommended_option": "Alternativa C: Estratégia Híbrida Sequencial - Consolidar Pecuária (Fase 1) e Preparar Industrial (Fase 2 Condicionada à SELIC)", "final_recommendation": "Adotar estratégia híbrida sequencial: intensificar Fase 1 com RFID e serviços recorrentes aproveitando regulamentação e Plano Safra, enquanto prepara Fase 2 industrial condicionada à queda da SELIC abaixo de 12%.", "priority_recommendations": [{"title": "Lançamento de Solução Integrada de Pesagem com RFID para Rastreabilidade Bovina", "budget": "R$ 300-450k", "priority": 1, "timeline": "6-12 meses", "description": "Desenvolver e comercializar pacote integrado de balança eletrônica + leitor RFID + software de gestão, antecipando a obrigatoriedade regulatória de rastreabilidade individual bovina. Focar em confinamentos e pecuaristas de médio/grande porte. Utilizar Plano Safra como alavanca de financiamento para clientes, contornando a barreira da SELIC alta. Incluir modelo de assinatura mensal para software e suporte técnico.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Contratar consultoria especializada em homologação INMETRO desde o início do desenvolvimento. Implementar Privacy by Design no software. Manter monitoramento ativo das portarias do MAPA sobre rastreabilidade para ajuste de roadmap.", "requires_legal_opinion": true, "regulatory_dependencies": ["Homologação INMETRO para novos modelos de balança com RFID integrado", "Conformidade com normas de rastreabilidade do MAPA", "Adequação LGPD para dados de clientes no software de gestão"], "requires_statutory_change": false}}, {"title": "Programa de Maximização da Base Instalada - Serviços Recorrentes e Contratos de Manutenção", "budget": "R$ 120-180k", "priority": 2, "timeline": "3-9 meses", "description": "Estruturar programa comercial agressivo para converter a base instalada de equipamentos em contratos de manutenção preventiva, calibração periódica e upgrade tecnológico. Meta: elevar receita de serviços de 5% para 15% do faturamento em 18 meses. Criar pacotes Bronze/Prata/Ouro com SLAs diferenciados. Implementar sistema de monitoramento remoto IoT para equipamentos novos, gerando receita recorrente de conectividade.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Manutenção de credenciamento junto ao INMETRO para serviços de calibração"], "requires_statutory_change": false}}, {"title": "Preparação Estratégica para Fase 2 Industrial (Gatilho: SELIC < 12%)", "budget": "R$ 80-120k (fase preparatória)", "priority": 3, "timeline": "12-24 meses (preparação) + execução condicionada", "description": "Iniciar estudos de mercado, mapeamento de clientes-alvo e desenvolvimento de protótipos para segmento industrial (mineração, siderurgia, logística) sem comprometer Capex significativo. Estabelecer parcerias estratégicas com integradores industriais para validar demanda. Criar célula de P&D dedicada com 2-3 engenheiros. Definir gatilho claro: investimento pesado em estrutura comercial e assistência técnica industrial somente quando SELIC recuar abaixo de 12% a.a.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "regulatory_dependencies": ["Futuras homologações INMETRO para novos produtos industriais", "Normas NR-12 para equipamentos industriais"], "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 172048, false, false, false, 'PT0XJZS2', '2025-11-28 18:15:56.408567+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-28 18:12:03.055173+00'::timestamptz, '2025-11-28 18:26:56.197934+00'::timestamptz, '2025-11-28 18:14:54.78661+00'::timestamptz, NULL)
