VALUES ('eaf69616-0708-4a29-a58e-734dcf7999b3', NULL, NULL, NULL, '{"summary": "Posição crítica: expertise forte mas PMF indefinido. Priorizar validação de modelo de valor percebido com precificação ROI antes de escalar. Janela de oportunidade curta.", "threats": [{"source": "fato", "content": "IA gratuita (ChatGPT/Claude) commoditiza mentorias básicas e comprime margens", "confidence": "Alta"}, {"source": "fato", "content": "Selic 14.90% torna empresas cautelosas com investimentos em treinamento", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Fadiga de mercado com cursos/mentorias online exige diferenciação radical", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Baixas barreiras de entrada atraem novos competidores rapidamente", "confidence": "Média"}], "strengths": [{"source": "fato", "content": "Expertise profunda do fundador em vendas consultivas e network estabelecido no setor comercial", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Posicionamento AI-first permite escalar mentoria sem diluir qualidade percebida", "confidence": "Média"}, {"source": "análise de mercado", "content": "Modelo híbrido (SaaS + Serviço) permite capturar valor em múltiplos pontos", "confidence": "Média"}, {"source": "fato", "content": "Câmbio favorável (R$5.34) protege contra competidores internacionais", "confidence": "Alta"}], "weaknesses": [{"source": "fato", "content": "Ausência de Product Market Fit validado trava crescimento e previsibilidade de receita", "confidence": "Alta"}, {"source": "feedback de clientes", "content": "Modelo coletivo percebido como valor diluído vs mentoria individual premium", "confidence": "Alta"}, {"source": "análise de mercado", "content": "Marca não consolidada como empresa de tecnologia dificulta diferenciação de consultorias", "confidence": "Média"}, {"source": "estimativa", "content": "Estrutura enxuta (1-10) limita capacidade de execução simultânea em vendas e produto", "confidence": "Média"}], "opportunities": [{"source": "análise de mercado", "content": "Consolidação do setor EdTech abre janela para posicionamento como líder de nicho em vendas", "confidence": "Média"}, {"source": "análise de mercado", "content": "Desenvolver IP proprietário de IA para criar barreira competitiva sustentável", "confidence": "Média"}, {"source": "estimativa", "content": "Modelo de precificação baseado em ROI comprovado reduz objeção de Selic alta (14.90%)", "confidence": "Média"}, {"source": "estimativa", "content": "Parcerias com CRMs e plataformas de vendas para distribuição escalável", "confidence": "Baixa"}]}'::jsonb, '{"legal": ["LGPD rigorosa para dados de funcionários: compliance obrigatório para vender a RH corporativo, exige investimento em segurança", "Regulação de IA generativa iminente: direitos autorais de conteúdo podem impactar uso de IA para criar materiais de mentoria", "Certificações de metodologia exigidas: falta de credenciais formais pode ser barreira em vendas para grandes empresas"], "social": ["Fadiga do mercado com cursos online: saturação de mentorias exige diferenciação clara de valor e resultados tangíveis", "Desemprego 5.60% baixo: profissionais empregados buscam upskilling, mas empresas hesitam em investir em coletivos", "Geração Z entrando em vendas: demanda por microlearning e formatos ágeis vs. mentorias longas tradicionais"], "summary": "Cenário desafiador: juros altos (14.90%) travam vendas B2B, IA gratuita commoditiza mentorias básicas, e fadiga de mercado exige diferenciação. Oportunidade: IA para escalar valor percebido e câmbio favorece soluções nacionais.", "economic": ["SELIC 14.90% encarece crédito: empresas cortam gastos discricionários como mentorias, impactando vendas B2B de ticket alto", "PIB +3.20% resiliente: demanda por capacitação comercial existe, mas ciclo de venda alongado por cautela financeira", "Câmbio R$5.34: ferramentas SaaS internacionais ficam caras, abrindo espaço para soluções nacionais como 10XMentorAI"], "political": ["Estabilidade política com atenção fiscal: ajustes orçamentários podem reduzir investimentos públicos em capacitação corporativa", "Marco Legal da IA em discussão: incerteza regulatória pode atrasar decisões de compra de soluções AI-first por empresas", "Política monetária contracionista mantida: pressão sobre PMEs clientes dificulta aprovação de orçamentos para treinamento"], "environmental": ["Serviços digitais sem impacto ambiental direto: ESG não é barreira, mas pode ser argumento de venda vs. treinamentos presenciais", "Pressão corporativa por sustentabilidade: empresas preferem soluções remotas, favorecendo modelo digital da 10XMentorAI", "Redução de deslocamentos corporativos: tendência pós-pandemia consolida aceitação de capacitação 100% online"], "technological": ["IA generativa gratuita (ChatGPT/Claude) substitui mentorias básicas: necessidade de entregar valor além do conteúdo genérico", "Hiperpersonalização via IA é novo padrão: oportunidade de usar IA para escalar mentoria mantendo percepção de exclusividade", "Concorrentes migrando para modelos AI-first: janela de diferenciação tecnológica se fechando rapidamente"]}'::jsonb, '{"summary": "Atratividade setorial baixa para novo entrante: alta rivalidade, compradores cautelosos (Selic 14.90%), ameaça crítica de substitutos gratuitos (IA) e baixas barreiras para novos competidores. PMF exige diferenciação radical via IP proprietário de IA, parcerias estratégicas e modelo de precificação baseado em ROI comprovado. Janela de oportunidade existe na consolidação do setor, mas requer execução rápida.", "buyer_power": "Alta. Selic 14.90% torna empresas cautelosas com gastos discricionários em T&D. Clientes exigem ROI comprovado antes de investir. Fadiga de mercado com mentorias online aumenta poder de barganha.", "supplier_power": "Baixa dependência de fornecedores físicos (serviços digitais). Custos operacionais pressionados, mas infraestrutura cloud e APIs de IA são commoditizadas com múltiplos provedores disponíveis.", "disruption_ai_data": "Alta. IA generativa é novo padrão (adoção alta no setor). Hiperpersonalização via dados é diferencial competitivo. Risco: IA commoditizada elimina vantagem se não houver IP proprietário.", "threat_substitutes": "Crítica. ChatGPT/Claude gratuitos substituem mentorias básicas. Microlearning e plataformas self-service capturam demanda. Percepção de que IA resolve sem mentor humano cresce.", "competitive_rivalry": "Mercado fragmentado com consolidação acelerada. VendaC, G4 e Growth Machine dominam mindshare. Migração de consultores para modelos híbridos AI-first intensifica disputa por atenção em mercado saturado de ofertas.", "threat_new_entrants": "Alta para consultoria (baixa barreira), baixa para tech proprietária. Marco Legal de IA e LGPD criam fricção regulatória. Qualquer consultor pode lançar ''mentoria com IA'' rapidamente.", "buyer_power_intensity": "Alta", "overall_attractiveness": "Baixa", "strategic_implications": ["Pivotar de mentoria coletiva para modelo híbrido: IA para escala + sessões individuais premium para justificar ticket e ROI tangível", "Desenvolver IP proprietário de IA (metodologia embarcada) para criar barreira competitiva contra commoditização", "Buscar parceria estratégica com player estabelecido (G4, CRM vendors) para acelerar distribuição e credibilidade", "Criar cases de ROI quantificáveis (ex: +X% conversão em Y dias) para superar cautela de compradores em cenário de juros altos"], "supplier_power_intensity": "Baixa", "disruption_ai_data_intensity": "Alta", "threat_substitutes_intensity": "Alta", "competitive_rivalry_intensity": "Alta", "power_partnerships_ecosystems": "Média-Alta. Consolidação EdTech cria oportunidades de M&A ou parcerias estratégicas. Integração com CRMs (Salesforce, HubSpot) e ecossistemas de vendas pode acelerar distribuição.", "threat_new_entrants_intensity": "Alta", "power_partnerships_ecosystems_intensity": "Média"}'::jsonb, '{"summary": "90 dias focados em validar nicho SaaS B2B, lançar diagnóstico AI e fechar 2-3 clientes premium com AI Co-Pilot, atingindo R$ 20-30k MRR.", "plan_90_days": [{"focus": "Fundação", "month": "Mês 1", "objective": "Validar nicho de founders SaaS B2B Série A e estruturar base legal/operacional para oferta premium", "investment": "R$ 8-15 mil", "key_results": ["Contatar 30 founders SaaS Série A via LinkedIn com taxa de resposta >25% (mínimo 8 conversas)", "Realizar 5 calls de descoberta e documentar padrões de dor e willingness-to-pay", "Obter parecer jurídico e adequação LGPD concluídos com contratos-modelo prontos"], "aligned_recommendation": "Validar Nicho Vertical: Founders de SaaS B2B em Série A"}, {"focus": "Crescimento", "month": "Mês 2", "objective": "Desenvolver MVP do Diagnóstico AI-Powered e fechar 2 pilotos de mentoria premium", "investment": "R$ 20-30 mil", "key_results": ["Lançar versão beta do diagnóstico de maturidade comercial com 50 usuários teste", "Converter 2 founders do nicho validado em clientes piloto (R$ 8-15k/mês cada)", "Definir arquitetura técnica do AI Co-Pilot com roadmap de 60 dias documentado"], "aligned_recommendation": "Lançar Diagnóstico de Maturidade Comercial Gratuito (AI-Powered)"}, {"focus": "Consolidação", "month": "Mês 3", "objective": "Consolidar oferta premium com AI Co-Pilot funcional e pipeline qualificado via diagnóstico", "investment": "R$ 25-40 mil", "key_results": ["Entregar AI Co-Pilot v1 para os 2 clientes piloto com NPS >8 coletado", "Gerar 20 leads qualificados via diagnóstico automatizado com >30% agendando call", "Atingir MRR de R$ 20-30k com 2-3 clientes ativos na mentoria premium"], "aligned_recommendation": "Reposicionar Oferta Core: Mentoria Individual Premium com AI Co-Pilot"}], "success_metrics": ["Taxa de conversão do nicho SaaS B2B Série A >15% (validação de PMF)", "MRR de R$ 20-30k ao final dos 90 dias com 2-3 clientes premium", "Pipeline de 20+ leads qualificados via diagnóstico automatizado"], "execution_phases": {"scale": {"focus": "Expansão controlada e diversificação de canais", "duration": "Meses 7-12", "objectives": ["Escalar para 15-25 clientes premium ativos", "Testar expansão para nichos adjacentes (scale-ups, corporate)", "Avaliar reintrodução de modelo coletivo com AI como diferencial"], "key_results": ["MRR de R$ 150-250k com margem >60%", "2 novos canais de aquisição validados além de outbound", "Decisão documentada sobre modelo coletivo v2"], "prerequisites": ["PMF validado com unit economics positivo (LTV/CAC >3)", "Processo de vendas replicável documentado", "AI Co-Pilot estável com churn <10%/mês"], "investment_range": "R$ 80-120 mil"}, "foundation": {"focus": "Validação de PMF e estruturação jurídica/operacional", "duration": "Meses 1-3", "objectives": ["Validar hipótese de nicho com dados reais de mercado", "Estruturar base legal para oferta AI-powered", "Desenvolver MVPs de diagnóstico e AI Co-Pilot"], "key_results": ["5+ calls de descoberta com founders SaaS Série A documentadas", "2 clientes piloto pagantes validando modelo premium", "Diagnóstico automatizado com 50+ usuários teste"], "investment_range": "R$ 53-85 mil", "capacity_requirements": {"team": "2-3 pessoas (Renato + 1 dev/no-code + 1 apoio comercial part-time)", "dependencies": ["Parecer jurídico sobre uso de IA em serviços", "Acesso à rede de founders via LinkedIn do Renato", "Ferramenta de automação para diagnóstico (Typeform/Make ou similar)"], "skills_needed": ["Desenvolvimento AI/automação (pode ser terceirizado)", "Vendas consultivas B2B", "Estruturação jurídica (terceirizado)"]}}, "validation": {"focus": "Escalar pilotos e refinar produto com feedback real", "duration": "Meses 4-6", "objectives": ["Expandir base de clientes premium para 5-8 ativos", "Iterar AI Co-Pilot baseado em feedback dos pilotos", "Automatizar funil diagnóstico → call → proposta"], "key_results": ["MRR de R$ 50-80k com 5-8 clientes ativos", "AI Co-Pilot v2 com 3+ iterações baseadas em uso real", "Taxa de conversão diagnóstico→cliente >10%"], "prerequisites": ["Mínimo 2 clientes piloto com feedback positivo (NPS >7)", "Diagnóstico gerando >10 leads qualificados/mês", "Contratos e termos jurídicos validados"], "investment_range": "R$ 40-60 mil"}}, "total_investment": "R$ 53-85 mil", "capacity_assessment": {"blockers": ["Capacidade de execução limitada pela estrutura enxuta (1-10 pessoas)", "Dependência alta do tempo do Renato para vendas e entrega simultâneas", "Orçamento restrito pode exigir priorização rigorosa entre diagnóstico e AI Co-Pilot"], "team_readiness": "Média", "budget_adequacy": "Limitado", "stakeholder_alignment": "Alinhado"}}'::jsonb, '{"roadmap": null, "key_findings": null, "main_findings": null, "important_notes": null, "central_challenge": "", "executive_summary": "", "strategic_priorities": null, "overall_recommendation": ""}'::jsonb, '{"sam": "R$ 1.8B - 3.5B", "som": "R$ 9M - 35M", "tam": "R$ 18B - 25B", "cagr": "+12% a.a. (baseado em: CAGR EdTech Latam 8% + premium IA +4%)", "summary": "Mercado de T&D em vendas com IA tem potencial de R$18-25B, mas 10XMentorAI precisa resolver PMF do modelo coletivo. SOM realista R$9-18M em 3 anos se pivotar para híbrido individual+coletivo.", "assumptions": ["TAM: Mercado T&D corporativo Brasil R$20B (ABTD 2024) + EdTech vendas R$3B", "SAM: 10-15% do TAM focado em treinamento de vendas B2B com tech/IA", "SOM: 0.5-1% do SAM realista para startup pré-PMF em 3 anos"], "som_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 9M - 18M", "market_share": "0.5-1.0%"}, "optimistic": {"probability": 20, "value_range": "R$ 18M - 35M", "market_share": "1.0-2.0%"}, "conservative": {"probability": 30, "value_range": "R$ 4M - 9M", "market_share": "0.2-0.5%"}}, "tam_scenarios": {"realistic": {"probability": 50, "value_range": "R$ 18B - 22B"}, "optimistic": {"probability": 20, "value_range": "R$ 22B - 28B"}, "conservative": {"probability": 30, "value_range": "R$ 15B - 18B"}}, "caveat_message": "⚠️ Estimativa baseada em benchmarks setoriais. Empresa em fase pré-PMF com modelo coletivo ainda não validado. Selic alta (14.90%) pressiona vendas B2B de tickets elevados. Recomenda-se validar PMF antes de projeções agressivas.", "confidence_level": 55, "calculation_notes": "Cruzamento de dados ABTD (T&D Brasil) com crescimento EdTech Latam. SAM filtrado para nicho vendas B2B com IA. SOM conservador dado estágio pré-PMF.", "data_sources_used": {"direct_data": ["CAGR E-learning Latam +8% (macro_context)", "Selic 14.90% impactando tickets altos B2B"], "proxy_calculations": ["Concorrentes G4/Growth Machine estimados R$50-200M/ano cada", "Mercado fragmentado com top 10 players ~15% share total"], "benchmark_extrapolations": ["EdTech Brasil TAM R$150-250B (benchmark geral)", "Subnicho T&D vendas ~10-12% do mercado educação corporativa"]}, "estimation_method": "benchmark_setorial", "baseline_recommendation": "conservative"}'::jsonb, '{"summary": "A 10XMentorAI enfrenta o desafio clássico de PMF em mentorias coletivas: o mercado brasileiro, especialmente em cenário de juros altos (14.90%), resiste a investimentos sem ROI comprovado e percebe modelos coletivos como ''cursos disfarçados''. Os concorrentes bem-sucedidos (G4, Growth Machine) resolveram isso com: (1) comunidade/networking como valor central, não apenas conteúdo; (2) metodologias proprietárias certificáveis; (3) modelos híbridos que iniciam com diagnóstico individual. A IA como diferencial só funciona se traduzida em personalização perceptível pelo cliente no modelo coletivo. Recomendação: pivotar para modelo ''coletivo personalizado'' onde a IA entrega trilhas individualizadas dentro de cohorts, combinando escala com percepção de exclusividade.", "best_practices": ["G4 Educação: Comunidade forte + eventos presenciais criam senso de pertencimento que justifica modelo coletivo", "Growth Machine: Metodologia proprietária documentada com certificação gera autoridade e diferenciação de mercado", "SalesFarm: Modelo híbrido (diagnóstico individual + implementação coletiva) resolve objeção de personalização"], "performance_gaps": ["Modelo coletivo sem diferenciação clara vs. cursos online massificados - percepção de commodity pelo cliente", "Ausência de cases quantificados de ROI que justifiquem ticket de mentoria coletiva em cenário de Selic 14.90%", "Falta de produto de entrada (freemium/low-ticket) para nutrir leads antes da venda de alto comprometimento"], "competitors_analyzed": ["VendaC", "SalesFarm", "G4 Educação", "Growth Machine", "Mentorias de Vendas Tradicionais"]}'::jsonb, '{"raise": ["Personalização via IA que simula mentoria 1:1 em escala coletiva", "Transparência de ROI com dashboard de métricas em tempo real", "Integração com CRM/ferramentas do cliente para ação imediata"], "create": ["Mentor AI proprietário treinado com IP exclusivo de vendas B2B", "Modelo de precificação por resultado (success fee + base mínima)", "Comunidade de prática com ranking gamificado e cases reais"], "reduce": ["Custo de aquisição via tráfego pago em mercado saturado", "Tempo entre contratação e primeiro resultado tangível do cliente", "Complexidade de onboarding e curva de aprendizado inicial"], "summary": "A estratégia transforma a 10XMentorAI de uma mentoria coletiva tradicional em uma plataforma de ''Mentor AI as a Service''. O diferencial radical está no IP proprietário de IA treinado com metodologia exclusiva de vendas B2B, modelo de precificação baseado em resultados (reduzindo risco do comprador em cenário de Selic alta) e entrega de valor contínua via agente de IA, eliminando a dependência de sessões ao vivo. Isso neutraliza a ameaça de substitutos gratuitos (ChatGPT genérico) e cria barreira de entrada via dados e metodologia proprietária.", "eliminate": ["Modelo de mentoria coletiva genérica sem diferenciação de perfil", "Dependência de agenda fixa do mentor para entrega de valor", "Promessas vagas de resultado sem métricas de ROI claras"], "new_value_curve": "IA proprietária que entrega mentoria personalizada 24/7 com ROI comprovado, eliminando a percepção de valor diluído do modelo coletivo."}'::jsonb, '{"summary": "Estratégia de PLG com IA como gancho de aquisição, escada de valor clara (free→coletiva→premium→enterprise) e foco em quick wins mensuráveis para superar objeção de valor diluído.", "leap_loop": {"name": "LEAP Loop", "type": "acquisition", "steps": ["Land: Conteúdo de alta conversão no LinkedIn (cases de vendas com IA) + SEO para ''mentoria vendas B2B'' + parcerias com comunidades de vendedores", "Engage: Diagnóstico gratuito de performance comercial via IA + webinars semanais com insights acionáveis de vendas consultivas", "Activate: Trial de 7 dias da mentoria coletiva com acesso ao mentor IA + primeira sessão ao vivo gratuita para demonstrar valor tangível", "Propagate: Programa de indicação com desconto mútuo + certificados compartilháveis + ranking público de top performers da comunidade"], "metrics": ["CAC (Custo de Aquisição por Canal)", "Taxa de Conversão Trial → Pagante", "Coeficiente Viral (K-factor)", "Custo por Lead Qualificado (CPL)"], "bottleneck": "Percepção de valor diluído em mentorias coletivas vs. individuais - prospects não enxergam ROI claro no modelo grupal"}, "scale_loop": {"name": "SCALE Loop", "type": "monetization", "steps": ["Satisfy: Entrega de quick wins mensuráveis nas primeiras 2 semanas + dashboards de progresso individual + acesso 24/7 ao mentor IA", "Convert: Modelo freemium (IA básica grátis) → Coletiva (R$297/mês) → Premium com sessões 1:1 (R$997/mês) - escada de valor clara", "Loop Back: Cohorts trimestrais com renovação automática + comunidade exclusiva de alumni + atualizações contínuas de metodologia", "Expand: Upsell para consultoria in-company + licenciamento da IA para equipes + certificação de multiplicadores internos"], "metrics": ["LTV (Lifetime Value por tier)", "Taxa de Churn Mensal", "NRR (Net Revenue Retention)", "ARPU (Receita Média por Usuário)"], "bottleneck": "Conversão de coletiva para premium - dificuldade em demonstrar valor incremental que justifique 3x o preço"}}'::jsonb, '{"realist": {"name": "Cenário Realista", "description": "SELIC mantém-se em 14.90%, empresas seguem cautelosas com gastos discricionários. Mercado fragmentado intensifica competição: G4, Growth Machine e ferramentas gratuitas (ChatGPT) pressionam. PIB resiliente (+3.20%) sustenta demanda mínima, mas ciclo de venda B2B se alonga. Fadiga de mercado exige diferenciação clara. 10XMentorAI precisa pivotar modelo coletivo para formato que demonstre valor tangível antes do caixa acabar.", "probability": 60, "required_actions": ["Pivotar de mentoria coletiva para modelo ''cohort-based'' com entregáveis mensuráveis", "Reduzir ticket médio inicial e criar upsell progressivo para mitigar objeção de preço", "Desenvolver diagnóstico gratuito via IA como porta de entrada no funil", "Focar em nicho específico (ex: SDRs de SaaS) para construir autoridade vertical"]}, "summary": "10XMentorAI opera em janela crítica de validação de PMF sob pressão macroeconômica severa (SELIC 14.90%). O cenário mais provável (60%) exige pivô do modelo coletivo para formato com valor tangível demonstrável e ciclo de venda curto. Riscos principais: commoditização por IA gratuita e fadiga de mercado. Oportunidades: câmbio favorece soluções nacionais e tendência de hiperpersonalização beneficia quem dominar IA aplicada. Recomendação estratégica: focar em nicho vertical específico, criar diagnóstico gratuito como porta de entrada, e manter runway conservador até PMF confirmado. Monitorar COPOM e movimentos de M&A como sinais antecedentes de mudança de cenário.", "optimistic": {"name": "Cenário Otimista", "description": "SELIC recua para 11% até 2026, liberando orçamentos de T&D corporativo. O Marco Legal da IA traz segurança jurídica, diferenciando players sérios. 10XMentorAI captura onda de hiperpersonalização (CAGR 8% EdTech) com modelo híbrido IA+mentoria. Câmbio a R$5.34 inviabiliza concorrentes internacionais. PMEs retomam investimentos em capacitação comercial, validando PMF de mentorias coletivas com ROI comprovado.", "probability": 20, "required_actions": ["Acelerar desenvolvimento de features de IA proprietária para criar barreiras de entrada", "Estruturar cases de ROI quantificado para apresentar a decisores de T&D corporativo", "Firmar parcerias com associações comerciais (ADVB, ABRADI) para ganhar credibilidade"]}, "pessimistic": {"name": "Cenário Pessimista", "description": "SELIC sobe para 16%+ com deterioração fiscal. Empresas cortam 100% de orçamento de treinamento. IA gratuita commoditiza completamente mentorias básicas. Consolidação do setor EdTech elimina players pequenos. Regulação de IA (Marco Legal) impõe custos de compliance inviáveis para startups bootstrapped. Desemprego sobe, profissionais autônomos não investem em capacitação. 10XMentorAI enfrenta runway crítico sem validação de PMF.", "probability": 20, "required_actions": ["Cortar custos fixos e operar em modo survival com runway mínimo de 12 meses", "Pivotar para consultoria individual high-ticket enquanto valida modelo escalável", "Buscar acqui-hire por player maior (G4, SalesFarm) como exit strategy"]}, "mitigation_tactics": ["Construir receita recorrente via assinatura de conteúdo IA (menor ticket, maior previsibilidade) em paralelo às mentorias", "Desenvolver metodologia proprietária certificável que não seja replicável por IA gratuita", "Criar comunidade engajada de alumni que gere prova social e indicações orgânicas", "Manter estrutura enxuta (1-10 pessoas) e terceirizar tecnologia até validar PMF completamente"], "early_warning_signals": ["Decisões do COPOM sobre SELIC: quedas sinalizam abertura de orçamentos B2B em 60-90 dias", "Movimentos de M&A no setor EdTech (aquisições de startups de IA por grandes grupos) indicam consolidação acelerada", "Aumento de buscas por ''treinamento de vendas com IA'' no Google Trends sinaliza demanda emergente", "Taxa de conversão de trials/diagnósticos gratuitos: queda de 20%+ indica fadiga de mercado ou proposta de valor fraca", "Anúncios de cortes de T&D por grandes empresas (via LinkedIn/mídia) antecipam retração do mercado"]}'::jsonb, '{"summary": "O BSC alinha a transformação de mentoria tradicional para ''Mentor AI as a Service'', priorizando receita recorrente baseada em resultados (financeiro), redução de risco do comprador em cenário de Selic alta (cliente), automação via agente de IA proprietário (processos) e construção de IP e dados exclusivos como barreira competitiva contra substitutos gratuitos (aprendizado).", "customer": ["Converter 30% dos leads com modelo de precificação por performance", "Atingir NPS 70+ demonstrando ROI mensurável aos clientes B2B"], "financial": ["Atingir R$ 500k ARR com modelo ''Mentor AI as a Service'' até 2025", "Alcançar 70% de receita recorrente via contratos baseados em resultados"], "learning_growth": ["Treinar IA com 100% do IP de metodologia de vendas do fundador", "Construir base de dados proprietária com 500+ casos de uso validados"], "internal_processes": ["Lançar agente de IA proprietário com metodologia exclusiva de vendas B2B", "Reduzir dependência de sessões ao vivo para menos de 20% da entrega"]}'::jsonb, '{"score": "8.2/10", "summary": "A análise multicriterial indica que o modelo coletivo atual é inviável sob pressão macroeconômica (SELIC 14.90%) e fadiga de mercado. A estratégia recomendada prioriza velocidade de validação com investimento mínimo: (1) Diagnóstico AI como porta de entrada de baixo atrito, (2) Mentoria Premium 1:1 com diferencial proprietário que justifica ticket alto, (3) Validação rápida de nicho vertical específico. Riscos jurídicos são majoritariamente baixos, com atenção especial à estruturação contratual do AI Co-Pilot (risco médio, requer parecer). Próximos passos imediatos: contratar desenvolvimento do diagnóstico (semana 1-2), estruturar contrato de mentoria premium com advogado (semana 2-3), iniciar outbound para founders SaaS (semana 3). Revisão quinzenal obrigatória até PMF confirmado.", "criteria": ["Velocidade de Validação de PMF (Peso 40%)", "Preservação de Runway sob SELIC 14.90% (Peso 35%)", "Diferenciação contra Commoditização por IA Gratuita (Peso 25%)"], "alternatives": ["Pivô para Diagnóstico AI + Mentoria Individual Premium", "Nicho Vertical Específico (SaaS B2B) com Modelo Híbrido", "Licenciamento de Metodologia AI para Consultorias Parceiras"], "review_cycle": {"frequency": "Quinzenal (durante fase de validação PMF) / Mensal (após PMF confirmado)", "extraordinary_triggers": ["Taxa de conversão do diagnóstico <5% após 200 leads", "Churn de clientes premium >20% no primeiro mês", "Mudança na SELIC >1.5 p.p. (impacto direto no apetite de compra B2B)", "Lançamento de feature similar por ChatGPT/Claude que comoditize diagnóstico", "Regulação do Marco Legal da IA que exija licenciamento específico", "Decisão judicial sobre responsabilidade de IA em consultoria", "Falha de compliance LGPD com notificação da ANPD", "Runway projetado <4 meses"]}, "score_comparison": "+31% acima da segunda opção (Nicho Vertical: 6.3/10)", "monitoring_metrics": ["Taxa de Conversão Diagnóstico → Lead Qualificado (meta: >25%)", "Ciclo Médio de Venda em Dias (meta: <20 dias)", "Ticket Médio de Mentoria Premium (meta: >R$ 10k/mês)", "CAC Payback Period (meta: <60 dias)", "NPS de Clientes Premium (meta: >70)", "Runway em Meses (meta: >6 meses sempre)", "Taxa de Retenção Mensal de Clientes Premium (meta: >85%)"], "recommended_option": "Pivô para Diagnóstico AI + Mentoria Individual Premium", "final_recommendation": "Pivotar imediatamente para modelo de Diagnóstico AI gratuito + Mentoria Premium 1:1 com AI Co-Pilot. Abandonar coletivo até PMF confirmado. Foco em nicho SaaS B2B Série A. Manter runway >6 meses.", "priority_recommendations": [{"title": "Lançar Diagnóstico de Maturidade Comercial Gratuito (AI-Powered)", "budget": "R$ 15-25k", "priority": 1, "timeline": "45-60 dias", "description": "Criar ferramenta de diagnóstico automatizado que avalia maturidade comercial do prospect em 5 minutos, gerando relatório personalizado com gaps identificados. Funciona como porta de entrada para qualificação e demonstração de valor tangível imediato. O diagnóstico captura dados para personalização da oferta premium subsequente, reduzindo ciclo de venda de 45 para 15 dias.", "legal_feasibility": {"risk_level": "Baixo", "mitigation_plan": "Implementar consentimento explícito no formulário e base legal de legítimo interesse para processamento. Custo de adequação: R$ 2-3k com advogado especializado.", "requires_legal_opinion": false, "regulatory_dependencies": ["Conformidade LGPD para coleta de dados do diagnóstico", "Política de privacidade atualizada no site"], "requires_statutory_change": false}}, {"title": "Reposicionar Oferta Core: Mentoria Individual Premium com AI Co-Pilot", "budget": "R$ 35-50k", "priority": 2, "timeline": "60-90 dias", "description": "Abandonar temporariamente modelo coletivo e focar em mentoria 1:1 de alto ticket (R$ 8-15k/mês) com diferencial de AI Co-Pilot exclusivo para o mentorado. O AI replica frameworks e metodologia do Renato, disponível 24/7 entre sessões. Modelo resolve objeção de ''valor diluído'' do coletivo e justifica premium pelo acesso exclusivo à inteligência proprietária.", "legal_feasibility": {"risk_level": "Médio", "mitigation_plan": "Parecer jurídico recomendado (R$ 3-5k) para estruturação contratual que limite responsabilidade por decisões tomadas com base em outputs da IA. Incluir cláusula de que IA é ferramenta de apoio, não substitui julgamento humano.", "requires_legal_opinion": true, "regulatory_dependencies": ["Contrato de prestação de serviços com cláusula de limitação de responsabilidade sobre recomendações da IA", "Termo de uso do AI Co-Pilot com disclaimers adequados", "Conformidade com Marco Legal da IA (em discussão)"], "requires_statutory_change": false}}, {"title": "Validar Nicho Vertical: Founders de SaaS B2B em Série A", "budget": "R$ 5-10k", "priority": 3, "timeline": "30-45 dias", "description": "Testar hipótese de nicho específico com 10-15 founders de SaaS B2B que levantaram Série A nos últimos 18 meses e precisam estruturar máquina de vendas. Perfil tem budget aprovado, urgência de crescimento e baixa sensibilidade a preço. Validação via outbound direcionado no LinkedIn usando rede existente do Renato. Se conversão >15%, expandir; se <10%, pivotar nicho.", "legal_feasibility": {"risk_level": "Baixo", "requires_legal_opinion": false, "requires_statutory_change": false}}]}'::jsonb, 'completed', NULL, 131131, false, false, false, '9GG72OTX', '2025-12-01 13:53:24.648748+00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-28 17:23:26.537433+00'::timestamptz, '2025-12-01 13:53:24.648748+00'::timestamptz, '2025-11-28 17:25:37.313613+00'::timestamptz, NULL)
